window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-715fdc544322bf62"]={"versions": [{"id": "FIG-715fdc544322bf62", "releases": ["R1.3.0", "R1.5.1", "R17-03_R1.1.0", "R17-10_R1.2.0", "R18-03_R1.4.0", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Serialisierungs- und Speicherlayout-Diagramm innerhalb der Protokollspezifikation des SOME/IP-Standards (AUTOSAR Classic & Adaptive Platform). Das Diagramm visualisiert die Anordnung der Datenfelder im SOME/IP-Payload beim Marshalling eines eindimensionalen dynamischen Arrays (<code>One-dimensional array (dynamic length)</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Protokollelemente und Maßangaben:</p>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld (<code>Length n</code>)</strong>: Präfix-Feld mit einer dargestellten Breite von 32 Bit zur Aufnahme der Gesamtlänge der nachfolgenden Nutzdaten.</li>\n<li><strong>Array-Elemente (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code> bis <code>Element_n</code>)</strong>: Sequentiell serialisierte Nutzdaten-Elemente des Arrays.</li>\n<li><strong>Auslassungszeichen (<code>...</code>)</strong>: Symbolisiert eine variable Anzahl weiterer Feldelemente zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n<li><strong>Größenangabe einzelnes Element (<code>element size e</code>)</strong>: Bemaßung der Bytegröße für ein Einzelelement (am Beispiel von <code>Element_1</code>).</li>\n<li><strong>Gesamtlängenbemaßung (<code>n [Bytes]</code>)</strong>: Horizontaler Doppelpfeil, der die Gesamtspanne von Beginn <code>Element_1</code> bis Ende <code>Element_n</code> umfasst.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung und Deserialisierung erfolgt strikt sequentiell:</p>\n<ol class=\"fig-list\">\n<li>Voranstellung eines Längenfeldes mit dem Wert <code>n</code>, der exakt die Anzahl der folgenden Bytes der Elemente <code>Element_1</code> bis <code>Element_n</code> angibt.</li>\n<li>Anschließende Bytestrom-Übertragung der einzelnen Array-Elemente in aufsteigender Indexreihenfolge.</li>\n<li>Bei statischer Elementgröße <code>e</code> bestimmt der Empfänger die Anzahl der Elemente arithmetisch durch Division (<code>n / e</code>).</li>\n<li>Bei dynamischer Elementgröße erfolgt das Parsen der Elemente sequentiell entlang der definierten Feldstrukturen bis zum Erreichen der Gesamtlänge von <code>n</code> Bytes.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben gemäß SOME/IP-Spezifikation (u. a. <code>[PRS_SOMEIP_00377]</code>):</p>\n<ul class=\"fig-list\">\n<li>Das Längenfeld quantifiziert ausschließlich die Länge der Nutzdaten (<code>n [Bytes]</code>) und schließt die eigene Bytegröße des Längenfeldes (hier 32 Bit / 4 Bytes) nicht ein.</li>\n<li>Implementierer müssen beachten, dass die konfigurierte Bitbreite des Längenfeldes typspezifisch festgelegt wird; ein Längenfeld von 0 Bit signalisiert feste Längen.</li>\n<li>Pufferüberläufe und Deserialisierungsfehler sind abzufangen, falls der tatsächliche Bytestrom vor Erreichen von <code>n</code> Bytes abbricht oder die Summe der geparsten dynamischen Elemente <code>n</code> überschreitet.</li>\n</ul>"}, {"id": "FIG-412d6e54cc396716", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Serialisierungs- und Speicherlayout-Diagramm innerhalb der Protokollspezifikation des SOME/IP-Standards (AUTOSAR Classic & Adaptive Platform). Das Diagramm visualisiert die Anordnung der Datenfelder im SOME/IP-Payload beim Marshalling eines eindimensionalen dynamischen Arrays (<code>One-dimensional array (dynamic length)</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Protokollelemente und Maßangaben:</p>\n<ul class=\"fig-list\">\n<li><strong>Längenfeld (<code>Length n</code>)</strong>: Präfix-Feld mit einer dargestellten Breite von 32 Bit zur Aufnahme der Gesamtlänge der nachfolgenden Nutzdaten.</li>\n<li><strong>Array-Elemente (<code>Element_1</code>, <code>Element_2</code>, <code>Element_3</code> bis <code>Element_n</code>)</strong>: Sequentiell serialisierte Nutzdaten-Elemente des Arrays.</li>\n<li><strong>Auslassungszeichen (<code>...</code>)</strong>: Symbolisiert eine variable Anzahl weiterer Feldelemente zwischen <code>Element_3</code> und <code>Element_n</code>.</li>\n<li><strong>Größenangabe einzelnes Element (<code>element size e</code>)</strong>: Bemaßung der Bytegröße für ein Einzelelement (am Beispiel von <code>Element_1</code>).</li>\n<li><strong>Gesamtlängenbemaßung (<code>n [Bytes]</code>)</strong>: Horizontaler Doppelpfeil, der die Gesamtspanne von Beginn <code>Element_1</code> bis Ende <code>Element_n</code> umfasst.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung und Deserialisierung erfolgt strikt sequentiell:</p>\n<ol class=\"fig-list\">\n<li>Voranstellung eines Längenfeldes mit dem Wert <code>n</code>, der exakt die Anzahl der folgenden Bytes der Elemente <code>Element_1</code> bis <code>Element_n</code> angibt.</li>\n<li>Anschließende Bytestrom-Übertragung der einzelnen Array-Elemente in aufsteigender Indexreihenfolge.</li>\n<li>Bei statischer Elementgröße <code>e</code> bestimmt der Empfänger die Anzahl der Elemente arithmetisch durch Division (<code>n / e</code>).</li>\n<li>Bei dynamischer Elementgröße erfolgt das Parsen der Elemente sequentiell entlang der definierten Feldstrukturen bis zum Erreichen der Gesamtlänge von <code>n</code> Bytes.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben gemäß SOME/IP-Spezifikation (u. a. <code>[PRS_SOMEIP_00377]</code>):</p>\n<ul class=\"fig-list\">\n<li>Das Längenfeld quantifiziert ausschließlich die Länge der Nutzdaten (<code>n [Bytes]</code>) und schließt die eigene Bytegröße des Längenfeldes (hier 32 Bit / 4 Bytes) nicht ein.</li>\n<li>Implementierer müssen beachten, dass die konfigurierte Bitbreite des Längenfeldes typspezifisch festgelegt wird; ein Längenfeld von 0 Bit signalisiert feste Längen.</li>\n<li>Pufferüberläufe und Deserialisierungsfehler sind abzufangen, falls der tatsächliche Bytestrom vor Erreichen von <code>n</code> Bytes abbricht oder die Summe der geparsten dynamischen Elemente <code>n</code> überschreitet.</li>\n</ul>"}], "trans": [{"from": "FIG-715fdc544322bf62", "to": "FIG-412d6e54cc396716", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
